def algorithm(func, dim, lb, ub, budget, rng):
    n = len(lb)
    x_best = 5 * np.ones(n)
    f_best = func(x_best)

    T = 1000.
    alpha = 1e-4

    for i in range(budget):
        sigma = 1 / (T + i) ** (1/3)

        def sample():
            while True:
                x_cand = np.clip(rng.normal(size=n, loc=x_best, scale=sigma), lb, ub)
                yield x_cand

        sample_iter = sample()
        for _ in range(dim):
            x_cand = next(sample_iter)
            f_cand = func(x_cand)

            if f_cand < f_best:
                f_best = f_cand
                x_best = x_cand

            if rng.rand() < np.exp((f_best - f_cand) / T):
                x_best = 0.5 * (x_best + x_cand)

        T *= (1 - alpha)

    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    def evaluate(x):
        if np.any(x < lb) or np.any(x > ub):
            return np.inf
        return func(x)

    x = rng.uniform(lb, ub, size=dim)
    best_x = x.copy()
    best_f = evaluate(x)

    for _ in range(budget):
        f = evaluate(x)
        if f < best_f:
            best_f = f
            best_x = x.copy()

        lambda_ = int(np.sqrt(4 * dim))
        y = rng.normal(size=lambda_)
        cov = np.eye(lambda_) + 0.1 * np.outer(y, y)

        for _ in range(lambda_):
            z = rng.normal(size=dim)
            v = np.dot(cov, z)
            u = np.maximum(np.minimum(v + x, ub), lb) - x
            w = np.sqrt(u / (1 + np.sum(u)))
            x += w

    return best_x
